            <?php if ($user['role'] === 'admin'): ?><section class="portal-panel"><p class="eyebrow">Work assignment</p><h2>Assign reviewer</h2><p class="small text-muted">Current reviewer: <?= e($application['assigned_reviewer']['full_name'] ?? 'Unassigned') ?></p><form method="post" action="/staff/application/assign" class="review-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="application_id" value="<?= (int) $application['id'] ?>"><label for="reviewer_id">Admissions reviewer</label><select class="form-select" id="reviewer_id" name="reviewer_id" required><option value="">Choose an active reviewer</option><?php foreach ($reviewers as $reviewer): if ($reviewer['id'] === $user['id']) continue; ?><option value="<?= (int) $reviewer['id'] ?>" <?= (int) ($application['assigned_reviewer']['id'] ?? 0) === (int) $reviewer['id'] ? 'selected' : '' ?>><?= e($reviewer['full_name']) ?></option><?php endforeach; ?></select><button type="submit" class="btn btn-outline-navy">Save assignment</button></form></section><?php endif; ?>
            <form method="get" action="<?= e('/staff/application/' . (int) $application['id']) ?>" class="filter-bar" data-auto-filter-form data-page-params="interviews_page" data-filter-target="interview-results"><input type="hidden" name="per_page" value="<?= (int) ($application['interviews_pagination']['page_size'] ?? 20) ?>"><div class="filter-field search-field"><label for="interviews_q">Search interviews</label><input class="form-control" id="interviews_q" name="interviews_q" value="<?= e($interviewFilters['interviews_q']) ?>" maxlength="180" placeholder="Interviewer or instructions" data-filter-search></div><div class="filter-field"><label for="interviews_status">Interview status</label><select class="form-select" id="interviews_status" name="interviews_status" data-filter-change><option value="">All statuses</option><?php foreach (['scheduled' => 'Scheduled', 'completed' => 'Completed', 'cancelled' => 'Cancelled', 'no_show' => 'No show'] as $key => $label): ?><option value="<?= e($key) ?>" <?= $interviewFilters['interviews_status'] === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="filter-actions"><button class="btn btn-outline-navy" type="button" aria-expanded="<?= $interviewDatePreset !== '' ? 'true' : 'false' ?>" aria-controls="interviewsAdvanced" data-advanced-toggle><i class="bi bi-sliders" aria-hidden="true"></i> More Filters <span class="application-advanced-count"><?= $interviewDatePreset !== '' ? '1' : '' ?></span></button><?php if (array_filter($interviewFilters) !== []): ?><a class="btn btn-link" href="<?= e('/staff/application/' . (int) $application['id'] . '?per_page=' . (int) ($application['interviews_pagination']['page_size'] ?? 20) . '#interview-results') ?>">Reset</a><?php endif; ?></div><section class="application-advanced-panel" id="interviewsAdvanced" aria-labelledby="interviewsAdvancedHeading" data-advanced-panel <?= $interviewDatePreset !== '' ? '' : 'hidden' ?>><div class="application-advanced-heading"><h3 id="interviewsAdvancedHeading">Advanced Filters</h3><button class="btn btn-sm btn-outline-navy" type="button" aria-label="Close advanced filters" data-advanced-close>Close</button></div><div class="filter-field"><label for="interviews_date_range">Interview date</label><select class="form-select" id="interviews_date_range" name="interviews_date_range" data-date-preset><option value="">Any date</option><option value="last7" <?= $interviewDatePreset === 'last7' ? 'selected' : '' ?>>Last 7 days</option><option value="last30" <?= $interviewDatePreset === 'last30' ? 'selected' : '' ?>>Last 30 days</option><option value="custom" <?= $interviewDatePreset === 'custom' ? 'selected' : '' ?>>Custom range</option></select><div class="application-custom-dates" data-custom-range <?= $interviewDatePreset === 'custom' ? '' : 'hidden' ?>><div><label class="visually-hidden" for="interviews_start_date">Start date</label><input class="form-control" id="interviews_start_date" name="interviews_start_date" type="date" value="<?= e($interviewFilters['interviews_start_date']) ?>" data-range-start></div><span>to</span><div><label class="visually-hidden" for="interviews_end_date">End date</label><input class="form-control" id="interviews_end_date" name="interviews_end_date" type="date" value="<?= e($interviewFilters['interviews_end_date']) ?>" data-range-end></div><small>Interview start date · Asia/Manila</small></div></div></section><?php $activeFilterChips = []; if ($interviewFilters['interviews_q'] !== '') $activeFilterChips[] = ['key' => 'interviews_q', 'label' => 'Search: ' . $interviewFilters['interviews_q']]; if ($interviewFilters['interviews_status'] !== '') $activeFilterChips[] = ['key' => 'interviews_status', 'label' => 'Interview status: ' . ucwords(str_replace('_', ' ', $interviewFilters['interviews_status']))]; if ($interviewDatePreset !== '') $activeFilterChips[] = ['key' => 'interviews_date_range', 'clear_keys' => ['interviews_date_range', 'interviews_start_date', 'interviews_end_date'], 'label' => 'Interview date: ' . ['last7' => 'Last 7 days', 'last30' => 'Last 30 days', 'custom' => trim($interviewFilters['interviews_start_date'] . ' to ' . $interviewFilters['interviews_end_date'])][$interviewDatePreset]]; $filterResetUrl = '/staff/application/' . (int) $application['id'] . '?per_page=' . (int) ($application['interviews_pagination']['page_size'] ?? 20) . '#interview-results'; require dirname(__DIR__) . '/partials/active-filter-chips.php'; ?><span class="visually-hidden" role="status" aria-live="polite" data-filter-status></span></form>
            <?php if ($application['interviews'] === [] && (($application['interviews_pagination']['total'] ?? 0) > 0 || array_filter($interviewFilters) !== [])): ?><p class="empty-note" id="interview-results">No interviews match these filters.</p><?php endif; ?>
            <?php foreach ($application['interviews'] as $interviewIndex => $interview): ?><section class="portal-panel"<?= $interviewIndex === 0 ? ' id="interview-results" data-pagination-target' : '' ?>><p class="eyebrow">Interview record</p><h2><?= e(ucwords(str_replace('_', ' ', $interview['status']))) ?></h2><p><?= e(date('M j, Y g:i A', strtotime($interview['starts_at_utc'] . ' UTC'))) ?> Asia/Manila</p><p class="small">Interviewer: <?= e($interview['interviewer_name'] ?? 'Not assigned') ?></p><?php if ($interview['instructions']): ?><p><?= nl2br(e($interview['instructions'])) ?></p><?php endif; ?><?php if ($interview['notes']): ?><p class="small">Notes: <?= nl2br(e($interview['notes'])) ?></p><?php endif; ?><?php if ($interview['status'] === 'scheduled'): ?><form method="post" action="/staff/interview/update" class="review-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="application_id" value="<?= (int) $application['id'] ?>"><input type="hidden" name="interview_id" value="<?= (int) $interview['id'] ?>"><label for="interview_result_<?= (int) $interview['id'] ?>">Outcome</label><select class="form-select" id="interview_result_<?= (int) $interview['id'] ?>" name="status"><option value="completed">Completed</option><option value="cancelled">Cancelled</option><option value="no_show">No show</option></select><label for="interview_notes_<?= (int) $interview['id'] ?>">Interview notes</label><textarea class="form-control" id="interview_notes_<?= (int) $interview['id'] ?>" name="notes" rows="3" maxlength="2000"></textarea><button class="btn btn-outline-navy" type="submit">Save interview outcome</button></form><?php endif; ?></section><?php endforeach; ?>
            <?php foreach ($application['interviews'] as $interview): if ($interview['status'] === 'scheduled'): $startsLocal = (new DateTimeImmutable($interview['starts_at_utc'], new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Manila'))->format('Y-m-d\TH:i'); $endsLocal = $interview['ends_at_utc'] ? (new DateTimeImmutable($interview['ends_at_utc'], new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Manila'))->format('Y-m-d\TH:i') : ''; ?><section class="portal-panel"><p class="eyebrow">Interview changes</p><h2>Reschedule interview</h2><form method="post" action="/staff/interview/reschedule" class="review-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="application_id" value="<?= (int) $application['id'] ?>"><input type="hidden" name="interview_id" value="<?= (int) $interview['id'] ?>"><label for="reschedule_interviewer_<?= (int) $interview['id'] ?>">Interviewer</label><select class="form-select" id="reschedule_interviewer_<?= (int) $interview['id'] ?>" name="interviewer_id" required><?php foreach ($reviewers as $reviewer): ?><option value="<?= (int) $reviewer['id'] ?>" <?= (int) $reviewer['id'] === (int) $interview['interviewer_id'] ? 'selected' : '' ?>><?= e($reviewer['full_name']) ?></option><?php endforeach; ?></select><label for="reschedule_start_<?= (int) $interview['id'] ?>">Start time (Asia/Manila)</label><input class="form-control" id="reschedule_start_<?= (int) $interview['id'] ?>" name="starts_at" type="datetime-local" value="<?= e($startsLocal) ?>" required><label for="reschedule_end_<?= (int) $interview['id'] ?>">End time (Asia/Manila)</label><input class="form-control" id="reschedule_end_<?= (int) $interview['id'] ?>" name="ends_at" type="datetime-local" value="<?= e($endsLocal) ?>" required><label for="reschedule_instructions_<?= (int) $interview['id'] ?>">Instructions</label><textarea class="form-control" id="reschedule_instructions_<?= (int) $interview['id'] ?>" name="instructions" rows="2" maxlength="1000"><?= e($interview['instructions'] ?? '') ?></textarea><button class="btn btn-outline-navy" type="submit" data-confirm="Reschedule this interview and notify the student?">Save new schedule</button></form></section><?php endif; endforeach; ?>
            <?php if (in_array($application['status'], ['in_screening', 'documents_incomplete'], true)): ?><section class="portal-panel"><p class="eyebrow">Applicant interview</p><h2>Schedule a time</h2><form method="post" action="/staff/interview/save" class="review-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="application_id" value="<?= (int) $application['id'] ?>"><label for="interviewer_id">Interviewer</label><select class="form-select" id="interviewer_id" name="interviewer_id" required><option value="">Choose an interviewer</option><?php foreach ($reviewers as $reviewer): ?><option value="<?= (int) $reviewer['id'] ?>"><?= e($reviewer['full_name']) ?></option><?php endforeach; ?></select><label for="interview_start">Start time (Asia/Manila)</label><input class="form-control" id="interview_start" name="starts_at" type="datetime-local" required><label for="interview_end">End time (Asia/Manila)</label><input class="form-control" id="interview_end" name="ends_at" type="datetime-local" required><label for="interview_instructions">Location or meeting instructions</label><textarea class="form-control" id="interview_instructions" name="instructions" rows="3" maxlength="1000"></textarea><button class="btn btn-outline-navy" type="submit" data-confirm="Schedule this interview and notify the student?">Schedule interview</button></form></section><?php endif; ?>
            <?php if ($user['role'] === 'admin' && $application['status'] === 'accepted'): ?><?php $checklist = is_array($application['enrollment']) && is_array(json_decode((string) $application['enrollment']['checklist'], true)) ? json_decode((string) $application['enrollment']['checklist'], true) : []; ?><section class="portal-panel"><p class="eyebrow">Enrollment preparation</p><h2>Readiness checklist</h2><form method="post" action="/staff/enrollment/checklist" class="review-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="application_id" value="<?= (int) $application['id'] ?>"><?php foreach (['offer_confirmed' => 'Admission offer confirmed', 'documents_checked' => 'Original documents checked', 'instructions_sent' => 'Enrollment instructions sent', 'registration_ready' => 'Registration preparation complete'] as $key => $label): ?><label class="consent-check"><input type="checkbox" name="checklist[]" value="<?= e($key) ?>" <?= !empty($checklist[$key]) ? 'checked' : '' ?>><span><?= e($label) ?></span></label><?php endforeach; ?><button class="btn btn-outline-navy" type="submit">Save checklist</button></form><p class="small text-muted">The application can be marked enrolled only after every checklist item is complete.</p></section><?php endif; ?>
            <section class="portal-panel"><p class="eyebrow">Decision workflow</p><h2>Update status</h2><?php $allowed = StatusTransitionPolicy::targets($application['status'], $user['role']); ?><?php if ($allowed === []): ?><p class="text-muted small">No further status transition is available.</p><?php else: ?><form method="post" action="/staff/application/status" class="review-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="application_id" value="<?= (int) $application['id'] ?>"><label for="status">Next status</label><select class="form-select" id="status" name="status" required><?php foreach ($allowed as $status): ?><option value="<?= e($status) ?>"><?= e($statusLabels[$status]) ?></option><?php endforeach; ?></select><label for="status_note">Decision note (optional)</label><textarea class="form-control" id="status_note" name="note" rows="3" maxlength="500"></textarea><button class="btn btn-amber w-100" type="submit" data-confirm="Update the application status and notify the student?">Save status update</button></form><?php endif; ?></section>
            <section class="portal-panel" id="status-history-results" data-pagination-target><p class="eyebrow">Application history</p><h2>Status changes</h2><?php if ($application['history'] === []): ?><p class="text-muted small">No status changes recorded yet.</p><?php else: ?><ol class="history-list"><?php foreach ($application['history'] as $event): ?><li><strong><?= e($statusLabels[$event['to_status']] ?? $event['to_status']) ?></strong><small><?= e(date('M j, Y g:i A', strtotime($event['created_at'] . ' UTC'))) ?></small><?php if ($event['note']): ?><p><?= e($event['note']) ?></p><?php endif; ?></li><?php endforeach; ?></ol><?php endif; ?></section>
            <?php if ($application['interviews'] !== []): $pagination = $application['interviews_pagination'] + ['target' => 'interview-results']; require dirname(__DIR__) . '/partials/pagination.php'; endif; ?>
            <?php if ($application['history'] !== []): $pagination = $application['history_pagination'] + ['target' => 'status-history-results']; require dirname(__DIR__) . '/partials/pagination.php'; endif; ?>
